`timescale 1ns/1ps
// Stage 1 test-only wide equal-selection rank oracle.
// PRECONDITION: build/foundation_weave_root.bin was generated by
// the *independent* 22528-bit full root-count SV module and its
// SHA-256 was verified by the runner. This test selects the rank,
// it does not implement the 4244-symbol lexical unranking.
module tb_weave_full_rank;
    localparam integer WIDTH=22528, ROOT_BYTES=2809, DIGITS=177;
    localparam logic [WIDTH-1:0] M=127'h7fffffffffffffffffffffffffffffff;
    localparam logic [127:0] A0=128'd106458209471735273212934705135928382248;
    logic [WIDTH-1:0] root_count,space,wide_minus_one;
    logic [WIDTH-1:0] accepted,limit,ordinal,remaining;
    logic [127:0] digit;
    integer file_in,file_out,codepoint,i,d,quotient;
    initial begin
        root_count='0;
        file_in=$fopen("build/foundation_weave_root.bin","rb");
        if(file_in==0) $fatal(1,"WIDE_RANK_MISSING_VERIFIED_ROOT");
        for(i=ROOT_BYTES-1;i>=0;i=i-1) begin
            codepoint=$fgetc(file_in);
            if(codepoint<0) $fatal(1,"WIDE_RANK_SHORT_ROOT");
            root_count[i*8 +:8]=codepoint[7:0];
        end
        if($fgetc(file_in)!=-1) $fatal(1,"WIDE_RANK_LONG_ROOT");
        $fclose(file_in);
        if(root_count[22469]!==1'b1 ||
           root_count[WIDTH-1:22470]!=='0)
            $fatal(1,"WIDE_RANK_ROOT_WIDTH");

        // Exact S=M^177 and exact 177 *consecutive* base-M digits
        // in least-significant-first canonical order.
        space=WIDTH'(1);
        for(i=0;i<DIGITS;i=i+1) space=space*M;
        wide_minus_one='0;
        for(i=DIGITS-1;i>=0;i=i-1) begin
            digit=A0-128'd1-$unsigned(i); // D is even: step=-1.
            wide_minus_one=wide_minus_one*M+digit;
        end
        if(space[22478]!==1'b1 ||
           space[WIDTH-1:22479]!=='0)
            $fatal(1,"WIDE_RANK_SPACE_BITS");
        if(wide_minus_one>=space)
            $fatal(1,"WIDE_RANK_INITIAL_OUTSIDE_RING");

        // Integer proof of floor(S/root)=555, without simulator
        // native / or %. Both products fit in WIDTH bits.
        limit=root_count*WIDTH'(555);
        if(limit>space || root_count*WIDTH'(556)<=space)
            $fatal(1,"WIDE_RANK_BOUND_QUOTIENT");
        // Initial answer = wide_minus_one+1. Exact rejection:
        // step=-1 => if initial>limit, first accepted=limit.
        accepted=(wide_minus_one+WIDTH'(1)<=limit) ?
                 wide_minus_one+WIDTH'(1) : limit;
        if(accepted!==wide_minus_one+WIDTH'(1))
            $fatal(1,"WIDE_RANK_UNEXPECTED_REJECTION");

        remaining=accepted-WIDTH'(1);
        quotient=0;
        while(remaining>=root_count && quotient<=555) begin
            remaining=remaining-root_count;
            quotient=quotient+1;
        end
        if(quotient>555 || remaining>=root_count)
            $fatal(1,"WIDE_RANK_LONG_DIVISION_BOUND");
        ordinal=remaining+WIDTH'(1);
        if(ordinal[22468]!==1'b1 ||
           ordinal[WIDTH-1:22469]!=='0)
            $fatal(1,"WIDE_RANK_ORDINAL_BIT_LENGTH");

        file_out=$fopen("build/foundation_weave_rank.bin","wb");
        if(file_out==0) $fatal(1,"WIDE_RANK_FILE_OPEN");
        for(i=ROOT_BYTES-1;i>=0;i=i-1)
            $fwrite(file_out,"%c",ordinal[i*8 +:8]);
        $fclose(file_out);
        $display("STAGE1_WIDE_WEAVE_RANK_SELECTED digits=177 domain_quotient=555 quotient=%0d bits=22469",
                 quotient);
        $finish;
    end
endmodule
